    acceptingUpdates = false;
    await Future.wait(updateEvents);
    return _ExecutedToolCallOutcome(
      _errorToolResult(error, toolName: toolCall.name),
      true,
      validationRejection:
          error is ToolValidationException || error is ToolNotFoundException,
    );
  }
}

