      // "immediately" knob (gh-1054 review).
      if (positive ? value <= 0 : value < 0) {
        throw ConfigException(
          '"agent.stuckTool.$key" must be '
          '${positive ? '> 0' : '>= 0'}',
        );
      }
      return value;
